if(!modes.some(x=>x[0]==="sentences"))modes.push(["sentences","Предлоги в предложениях"]);
const ypkSentenceHero=document.createElement("button");
ypkSentenceHero.className="prep-hero sentence-hero";
ypkSentenceHero.innerHTML="<b>Предлоги в предложениях</b><span>18 заданий · перевод и повтор ошибок</span>";
$("prepHero").after(ypkSentenceHero);
ypkSentenceHero.onclick=()=>setMode("sentences");
const ypkBaseSetMode=setMode;
setMode=function(mode){if(mode==="sentences"){state.sentenceQueue=[];state.sentenceResults=[]}ypkBaseSetMode(mode)};
const ypkBaseRenderPanelForSentences=renderPanel;
renderPanel=function(){if(state.mode==="sentences")ypkRenderSentence();else ypkBaseRenderPanelForSentences()};
const ypkBaseCurrentWordForSentences=ypkCurrentWord;
ypkCurrentWord=function(){if(state.mode==="sentences"){const s=state.sentenceQueue?.[state.i];if(s)return {en:ypkFillSentence(s),ru:s[2]}}return ypkBaseCurrentWordForSentences()};
const ypkBaseRevealForSentences=ypkReveal;
ypkReveal=function(){
  if(state.mode!=="sentences"){ypkBaseRevealForSentences();return}
  const sentence=state.sentenceQueue?.[state.i];
  const bar=$("panel").querySelector(".study-tools");
  let box=$("revealBox");if(!box){box=document.createElement("div");box.id="revealBox";box.className="reveal-box";bar?bar.before(box):$("panel").append(box)}
  box.innerHTML=sentence?`<b>Правильный ответ</b><span>${esc(ypkFillSentence(sentence))}</span><small><strong>Перевод:</strong> ${esc(sentence[2])}</small><small>${esc(sentence[3])}</small>`:"<b>Серия завершена</b>";
  const button=$("revealTranslation");if(button)button.textContent="Перевод показан";
};

function ypkFillSentence(sentence){let index=0;return sentence[0].replace(/___/g,()=>sentence[1][index++])}
function ypkStartSentences(){state.sentenceUnit=state.unit;state.sentenceQueue=state.randomOrder?shuffle(ypkSentenceBank[state.unit]):[...ypkSentenceBank[state.unit]];state.sentenceCount=state.sentenceQueue.length;state.sentenceResults=[];state.sentenceMistakes=new Map();state.i=0}
function ypkRenderSentence(){
  if(state.sentenceUnit!==state.unit||!state.sentenceQueue?.length)ypkStartSentences();
  const item=state.sentenceQueue[state.i],count=state.sentenceCount;
  if(!item){
    const firstTry=state.sentenceResults.slice(0,count).filter(r=>r?.ok).length;
    const mistakes=[...(state.sentenceMistakes||new Map()).values()];
    $("panel").innerHTML=`<div class="eyebrow">Предлоги в предложениях · Unit ${state.unit}</div><div class="game-score">${firstTry}/${count}</div><p class="definition">Верно с первой попытки. Предложения с ошибками повторялись до правильного ответа.</p>${mistakes.length?`<div class="test-review"><b>Предложения, в которых были ошибки</b>${mistakes.map(item=>`<div class="test-row bad"><b>${esc(ypkFillSentence(item))}</b><br><small>${esc(item[2])}</small></div>`).join("")}</div>`:'<div class="feedback good">Ошибок не было!</div>'}<div class="actions"><button class="primary" id="sentencesAgain">Новая серия</button></div>`;
    $("sentencesAgain").onclick=()=>{ypkStartSentences();ypkRenderSentence()};
    ypkEnsureTools();return;
  }
  const answered=state.sentenceResults[state.i],parts=item[0].split("___");
  const sentenceHtml=parts.map((part,index)=>`${esc(part)}${index<item[1].length?`<input class="sentence-gap" data-gap="${index}" aria-label="Предлог ${index+1}" autocomplete="off" autocapitalize="off" spellcheck="false" ${answered?`value="${esc(answered.values[index])}" disabled`:""}>`:""}`).join("");
  const progress=Math.round(Math.min(state.i/count,1)*100);
  $("panel").innerHTML=`<div class="eyebrow">Предлоги в предложениях · Unit ${state.unit} · ${state.i+1} из ${state.sentenceQueue.length}</div><div class="test-progress"><i style="width:${progress}%"></i></div><p class="definition">Впиши подходящие предлоги в пропуски. Регистр букв не важен.</p><div class="sentence-prompt">${sentenceHtml}</div>${answered?`<div class="feedback ${answered.ok?"good":"bad"}">${answered.ok?"Верно!":"Правильный вариант:"} <b>${esc(ypkFillSentence(item))}</b><br><small>${esc(item[2])}</small><br><small>${esc(item[3])}</small></div><div class="actions"><button class="primary" id="sentenceNext">Следующее предложение</button></div>`:`<div class="actions"><button class="primary" id="sentenceCheck">Проверить</button></div><div class="feedback">Можно открыть перевод и объяснение кнопкой ниже.</div>`}`;
  if(answered){$("sentenceNext").onclick=()=>{state.i++;ypkRenderSentence()}}
  else{
    const check=()=>{
      const values=[...$("panel").querySelectorAll(".sentence-gap")].map(input=>input.value.trim());
      if(values.some(value=>!value)){const feedback=$("panel").querySelector(".feedback");feedback.textContent="Заполни все пропуски перед проверкой.";return}
      const ok=values.every((value,index)=>norm(value)===norm(item[1][index]));
      state.sentenceResults[state.i]={ok,values};
      if(ok)state.score++;else{state.sentenceQueue.push(item);state.sentenceMistakes.set(item[0],item)}
      save();renderStats();ypkRenderSentence();
    };
    $("sentenceCheck").onclick=check;
    $("panel").querySelectorAll(".sentence-gap").forEach(input=>input.onkeydown=e=>{if(e.key==="Enter")check()});
  }
  ypkEnsureTools();
}
renderModes();
